#!/bin/bash
# Acceptance for `vizzle hybrid` against h, the repository whose generator it
# replaced (docs/plans/impl/hybrid.md §5.1, §5.2, §5.4):
#
#   1. byte-identical: building h's specs with this checkout's vizzle gives
#      h's committed SVGs, every line but the `GENERATED by` comment;
#   4. --check: 0 on a fresh set, 1 after one SVG is hand-edited, 2 on a
#      misspelt field;
#   2. drift, live: a renamed module, a new package in a pass scope and a
#      deleted cited path each exit 1 naming the box; each restored exits 0.
#
# Why it exists: the port is proved by output, not by reading it. The h
# checkout is never touched — everything runs on a `git archive` of its HEAD
# in a temp directory, which is also the "throwaway copy of h" §5.2 asks for.
#
# Usage: scripts/hybrid-acceptance.sh <h checkout>
# Exit 0 only when every step gave the expected result.

set -euo pipefail

VIZZLE_ROOT=$(cd "$(dirname "$0")/.." && pwd)

vizzle() { uv run --project "$VIZZLE_ROOT" --quiet vizzle "$@"; }

FAILED=0
pass() { echo "  ok   $*"; }
fail() { echo "  FAIL $*"; FAILED=1; }

# expect <code> <grep pattern | -> <label> -- <vizzle args…>: run, check the exit code and the output
expect() {
  local want=$1 pattern=$2 label=$3
  shift 4
  local out code=0
  out=$(vizzle "$@" 2>&1) || code=$?
  if [ "$code" -ne "$want" ]; then
    fail "$label: exit $code, wanted $want"
    echo "$out" | sed 's/^/         /' | tail -5
  elif [ "$pattern" != "-" ] && ! grep -qF -- "$pattern" <<<"$out"; then
    fail "$label: exit $code but no line containing: $pattern"
    echo "$out" | sed 's/^/         /' | tail -5
  else
    pass "$label: exit $code"
    [ "$pattern" = "-" ] || grep -F -- "$pattern" <<<"$out" | head -1 | sed 's/^/         /'
  fi
}

main() {
  local h=${1:?usage: $0 <h checkout>}
  TMP=$(mktemp -d)
  trap 'rm -rf "$TMP"' EXIT
  local tmp=$TMP
  local copy=$tmp/h
  mkdir -p "$copy"
  git -C "$h" archive HEAD | tar -x -C "$copy"
  local specs=$copy/docs/diagrams/hybrid
  echo "h: $(git -C "$h" rev-parse --short HEAD) ($(git -C "$h" branch --show-current)); vizzle: $(vizzle --version)"

  echo
  echo "§5.1 byte-identical (every line but the GENERATED comment)"
  vizzle hybrid --root "$copy" 2>&1 | grep -v '^wrote ' || true
  local n=0 same=0 name
  for spec in "$specs"/*.json; do
    name=$(basename "$spec" .json)
    [ "$name" = vizzle-passes ] && continue
    n=$((n + 1))
    if diff <(git -C "$h" show "HEAD:docs/diagrams/$name.svg" | grep -v '^<!-- GENERATED by ') \
      <(grep -v '^<!-- GENERATED by ' "$copy/docs/diagrams/$name.svg") >/dev/null; then
      same=$((same + 1))
      pass "$name.svg identical ($(wc -c <"$copy/docs/diagrams/$name.svg" | tr -d ' ') bytes)"
    else
      fail "$name.svg differs"
    fi
  done
  echo "  $same of $n identical. The one line that differs, for $name:"
  diff <(git -C "$h" show "HEAD:docs/diagrams/$name.svg") "$copy/docs/diagrams/$name.svg" | sed 's/^/         /' || true

  echo
  echo "§5.4 --check"
  expect 0 "matches its spec" "fresh set" -- hybrid --check --root "$copy"
  local edited=$copy/docs/diagrams/system-runtime.svg
  cp "$edited" "$tmp/saved.svg"
  sed -i.bak 's/fill="#ffffff"/fill="#fffffe"/' "$edited"
  expect 1 "system-runtime: docs/diagrams/system-runtime.svg differs" "one SVG hand-edited" -- hybrid --check --root "$copy"
  cp "$tmp/saved.svg" "$edited"
  local misspelt=$specs/workflow-concept.json
  cp "$misspelt" "$tmp/saved.json"
  sed -i.bak 's/"nodes":/"nodez":/' "$misspelt"
  expect 2 "unknown field \`nodez\`" "a misspelt field (nodez)" -- hybrid --check --root "$copy"
  cp "$tmp/saved.json" "$misspelt"
  expect 0 - "everything restored" -- hybrid --check --root "$copy"

  echo
  echo "§5.2 drift, live"
  local mod=$copy/cli/h/src/h_cli/commands
  mv "$mod" "$copy/cli/h/src/h_cli/cmds"
  # named, because a concept spec also cites a file in that directory and would trip first
  expect 1 "names sn:cli/h/src/h_cli/commands, which vizzle no longer reports" \
    "a module a runtime spec names is renamed" -- hybrid system-runtime --check --root "$copy"
  mv "$copy/cli/h/src/h_cli/cmds" "$mod"
  expect 0 - "renamed back" -- hybrid --check --root "$copy"

  local fresh=$copy/packages/js/single-node-runtime/src/newpart
  mkdir -p "$fresh"
  echo 'export class NewPart {}' >"$fresh/index.ts"
  expect 1 "vizzle reports sn:packages/js/single-node-runtime/src/newpart in scope, but the spec places it nowhere" \
    "a package added inside a pass scope" -- hybrid --check --root "$copy"
  rm -r "$fresh"
  expect 0 - "package removed" -- hybrid --check --root "$copy"

  local cited
  # the first node of a concept spec that cites a path: "<id> <path>"
  cited=$(python3 -c 'import json, sys
for n in json.load(open(sys.argv[1]))["nodes"]:
    p = n.get("path")
    if p:
        print(n["id"], p if isinstance(p, str) else p[0])
        break' "$specs/chain-concept.json")
  local node=${cited%% *} path=${cited#* }
  mv "$copy/$path" "$tmp/cited"
  expect 1 "$node cites $path, which is gone from the tree" "a path a concept spec cites is deleted" -- hybrid --check --root "$copy"
  mv "$tmp/cited" "$copy/$path"
  expect 0 - "path restored" -- hybrid --check --root "$copy"

  echo
  if [ "$FAILED" -eq 0 ]; then echo "acceptance: all passed"; else echo "acceptance: FAILED"; fi
  return "$FAILED"
}

main "$@"
